<?php
namespace App\Http\Controllers\Admin;
use App\Enums\UserRole;use App\Http\Controllers\Controller;use App\Models\ImportBatch;use App\Models\Organization;use App\Models\Person;use App\Models\RoleAssignment;use App\Models\User;use App\Services\AuditService;use App\Services\SpreadsheetReader;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Inertia\Inertia;use Inertia\Response;
class AuthorizationImportController extends Controller{public function index():Response{return Inertia::render('admin/AuthorizationImport',['batches'=>ImportBatch::where('type','authorization')->latest()->paginate(20)]);}public function preview(Request $r,SpreadsheetReader $reader):RedirectResponse{$r->validate(['file'=>'required|file|max:5120']);$rows=$reader->rows($r->file('file'));$map=array_flip(array_map('trim',array_shift($rows)?:[]));$required=['工号/统一账号','姓名','学院代码','岗位角色','启用状态'];foreach($required as $h)abort_unless(isset($map[$h]),422,"缺少列：$h");$payload=[];$errors=[];$seen=[];foreach($rows as $i=>$row){if(!array_filter($row))continue;$item=['employee_no'=>trim((string)($row[$map['工号/统一账号']]??'')),'name'=>trim((string)($row[$map['姓名']]??'')),'organization_code'=>trim((string)($row[$map['学院代码']]??'')),'position'=>trim((string)($row[$map['岗位角色']]??'')),'enabled'=>trim((string)($row[$map['启用状态']]??''))==='启用'];$p=Person::where('employee_no',$item['employee_no'])->first();$o=Organization::where('external_code',$item['organization_code'])->first();$es=[];if(isset($seen[$item['employee_no']]))$es[]='工号重复';$seen[$item['employee_no']]=true;if(!$p)$es[]='人员不存在';elseif($p->name!==$item['name'])$es[]='姓名不一致';if(!$o)$es[]='学院不存在';elseif($p&&$p->organization_id!==$o->id)$es[]='人员不属于该学院';if(!in_array($item['position'],['组织员','办公室主任']))$es[]='岗位角色无效';$payload[]=$item;if($es)$errors[]=['line'=>$i+2,'employee_no'=>$item['employee_no'],'messages'=>$es];}$batch=ImportBatch::create(['type'=>'authorization','status'=>$errors?'invalid':'preview','payload'=>$payload,'errors'=>$errors?:null,'created_by'=>$r->user()->id]);return redirect()->route('admin.authorization-import.index')->with($errors?'error':'success',$errors?'预览发现错误，请修正后重新上传。':'预览通过，共 '.count($payload).' 条。')->with('batch_id',$batch->id);}public function commit(Request $r,ImportBatch $batch,AuditService $a):RedirectResponse{abort_unless($batch->type==='authorization'&&$batch->status==='preview'&&empty($batch->errors),422);DB::transaction(function()use($batch,$r){foreach($batch->payload as $item){$p=Person::where('employee_no',$item['employee_no'])->where('status','active')->firstOrFail();$u=User::firstOrCreate(['cas_account'=>$p->employee_no],['person_id'=>$p->id,'name'=>$p->name,'email'=>$p->email?:$p->employee_no.'@invalid.local','password'=>bcrypt(Str::random(64)),'is_active'=>true]);$ra=RoleAssignment::withTrashed()->firstOrNew(['user_id'=>$u->id,'role'=>UserRole::CollegeSubmitter->value,'organization_id'=>$p->organization_id]);$ra->granted_by=$r->user()->id;if($item['enabled']){$ra->deleted_at=null;$ra->save();}elseif($ra->exists&&!$ra->trashed())$ra->delete();}$batch->update(['status'=>'committed','committed_at'=>now()]);});$a->record('authorization.committed',$batch,['rows'=>count($batch->payload)]);return back()->with('success','授权名单已生效。');}}
